def resolve_module_var(var_name: str):
    """Return the value of a module-level list/dict by name (used by ``--rename_v`` / ``--view_v``).

    Raises ``AttributeError`` if the name isn't bound in this module.
    """
    import sys
    return getattr(sys.modules[__name__], var_name)
